// NO USER EDITS HERE. Configure the preceding "EDIT HERE — URL, Checks & Alerts" (Edit Fields) node.
// This node validates the form and turns its check rows into structured assertions.
const f = $input.first().json;
function mustText(value, name) {
  const str = String(value ?? '').trim();
  if (!str) throw new Error('Missing ' + name + '. Open EDIT HERE — URL, Checks & Alerts.');
  return str;
}
const settings = {
  monitorKey: mustText(f.monitorKey, 'monitorKey'),
  monitorName: mustText(f.monitorName, 'monitorName'),
  targetUrl: mustText(f.targetUrl, 'targetUrl'),
  expectedHttpStatus: Number(f.expectedHttpStatus),
  reminderHours: Number(f.reminderHours),
  notifyOnRecovery: f.notifyOnRecovery === true || f.notifyOnRecovery === 'true',
  slackChannelId: mustText(f.slackChannelId, 'slackChannelId'),
  checks: [],
};
// Avoid global URL constructor: it is unavailable in some n8n Code sandboxes.
const urlParts = /^https:\/\/([^\/\?#\s]+)(?:[\/\?#]|$)/i.exec(settings.targetUrl);
if (!urlParts || !urlParts[1] || urlParts[1].includes('@') || settings.targetUrl.includes(' ')) {
  throw new Error('targetUrl must be an HTTPS JSON GET endpoint without embedded credentials. Set it in EDIT HERE — URL, Checks & Alerts.');
}
if (!Number.isInteger(settings.expectedHttpStatus) || settings.expectedHttpStatus < 100 || settings.expectedHttpStatus > 599) {
  throw new Error('expectedHttpStatus must be a valid HTTP status number (such as 200).');
}
if (!Number.isFinite(settings.reminderHours) || settings.reminderHours <= 0) {
  throw new Error('reminderHours must be greater than zero.');
}
const supportedRules = new Set(['equals', 'nonEmpty', 'minItems', 'freshWithinMinutes']);
// Four editable rows. Leave an unused check's Path, Rule and Expected blank.
for (let i=1;i<=4;i++) {
  const path = String(f['check'+i+'Path'] ?? '').trim();
  const rule = String(f['check'+i+'Rule'] ?? '').trim();
  const literal = String(f['check'+i+'Expected'] ?? '').trim();
  if (!path && !rule && !literal) continue;
  if (!path) throw new Error('check'+i+'Path is required, or clear the entire row.');
  if (!supportedRules.has(rule)) throw new Error('check'+i+'Rule must be equals, nonEmpty, minItems or freshWithinMinutes.');
  const check = {path,rule};
  if (rule !== 'nonEmpty') {
    if (!literal) throw new Error('check'+i+'Expected is required for '+rule+'.');
    if (rule === 'equals') {
      // JSON literals give real booleans and numbers; ordinary words remain strings.
      try { check.expected = JSON.parse(literal); }
      catch { check.expected = literal; }
    } else {
      const n = Number(literal);
      if (!Number.isFinite(n) || n < 0 || (rule === 'minItems' && !Number.isInteger(n)) || (rule === 'freshWithinMinutes' && n === 0)) {
        throw new Error('check'+i+'Expected must be a valid non-negative number ('+rule+').');
      }
      check.expected=n;
    }
  } else if (literal) {
    throw new Error('check'+i+'Expected must be empty when check'+i+'Rule is nonEmpty.');
  }
  settings.checks.push(check);
}
if (!settings.checks.length) throw new Error('Add at least one business validation rule in EDIT HERE — URL, Checks & Alerts.');
if (!/^(?:[CG][A-Z0-9]+|REPLACE_WITH_SLACK_CHANNEL_ID)$/.test(settings.slackChannelId)) {
  throw new Error('slackChannelId must be a Slack channel ID (e.g. C012ABC123), NOT the bot token.');
}
return [{json:settings}];

// Evaluate ONLY declared downstream contract fields. Never forward raw response data to Slack.
const cfg = $('Validate Monitor Setup').first().json;
const response = $input.first().json || {};
const issues = [];
const code = Number(response.statusCode ?? response.status ?? 0);
const expectedCode = Number(cfg.expectedHttpStatus);
if (response.error) issues.push('NETWORK_OR_HTTP_NODE_ERROR');
if (code !== expectedCode) issues.push('HTTP_STATUS_' + (code || 'UNKNOWN') + '_EXPECTED_' + expectedCode);
let body = response.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { issues.push('RESPONSE_NOT_VALID_JSON'); }
}
if (body === undefined || body === null || typeof body !== 'object') {
  issues.push('NO_JSON_OBJECT_OR_ARRAY');
}
function readPath(object, path) {
  if (!path || typeof path !== 'string') return { found: true, value: object };
  const parts = path.replace(/\[(\d+)\]/g, '.$1').split('.').filter(Boolean);
  let cur = object;
  for (const part of parts) {
    if (cur === null || cur === undefined || !Object.prototype.hasOwnProperty.call(Object(cur), part)) {
      return { found: false, value: undefined };
    }
    cur = cur[part];
  }
  return { found: true, value: cur };
}
function hasValue(v) {
  if (v === undefined || v === null) return false;
  if (typeof v === 'string') return v.trim().length > 0;
  if (Array.isArray(v)) return v.length > 0;
  if (typeof v === 'object') return Object.keys(v).length > 0;
  return true;  // 0 and false ARE valid business values
}
if (body !== null && typeof body === 'object') {
  for (const check of cfg.checks) {
    const path = check.path || '(root)';
    const result = readPath(body, check.path);
    const v = result.value;
    if (!result.found) { issues.push('MISSING_FIELD: ' + path); continue; }
    if (check.rule === 'nonEmpty') {
      if (!hasValue(v)) issues.push('EMPTY_FIELD: ' + path);
    } else if (check.rule === 'equals') {
      if (JSON.stringify(v) !== JSON.stringify(check.expected)) issues.push('UNEXPECTED_VALUE: ' + path);
    } else if (check.rule === 'minItems') {
      if (!Array.isArray(v) || v.length < Number(check.expected)) issues.push('TOO_FEW_ITEMS: ' + path);
    } else if (check.rule === 'freshWithinMinutes') {
      const parsed = typeof v === 'string' || typeof v === 'number' ? Date.parse(v) : NaN;
      const age = Date.now() - parsed;
      if (!Number.isFinite(parsed) || age < -5 * 60000 || age > Number(check.expected) * 60000) {
        issues.push('STALE_OR_INVALID_TIMESTAMP: ' + path);
      }
    } else {
      issues.push('INVALID_CONFIG_RULE: ' + path);
    }
  }
}
const unique = [...new Set(issues)].sort();
return [{ json: {
  monitorKey: cfg.monitorKey, monitorName: cfg.monitorName,
  slackChannelId: cfg.slackChannelId, reminderHours: cfg.reminderHours,
  notifyOnRecovery: cfg.notifyOnRecovery, checkedAt: new Date().toISOString(),
  responseStatus: code || null, healthy: unique.length === 0,
  issues: unique, fingerprint: unique.join('|') || 'HEALTHY',
} }];

// Persistent state is small: one entry per monitorKey. Changes save after a successful
// *production* execution (activated Schedule Trigger); manual tests do NOT save state.
const current = $input.first().json;
const states = $getWorkflowStaticData('global');
if (!states.canaryStatus || typeof states.canaryStatus !== 'object') states.canaryStatus = {};
const key = current.monitorKey;
const prev = states.canaryStatus[key] || null;
const now = Date.now();
const reminderMs = Math.max(1, Number(current.reminderHours) || 24) * 3600000;
let alertType = '';
if (!current.healthy) {
  if (!prev || prev.healthy) alertType = 'NEW_FAILURE';
  else if (prev.fingerprint !== current.fingerprint) alertType = 'FAILURE_CHANGED';
  else if (!prev.lastAlertAt || now - prev.lastAlertAt >= reminderMs) alertType = 'STILL_FAILING';
} else if (prev && !prev.healthy && current.notifyOnRecovery) {
  alertType = 'RECOVERED';
}
states.canaryStatus[key] = {
  healthy: current.healthy, fingerprint: current.fingerprint,
  lastCheckedAt: current.checkedAt,
  lastHealthyAt: current.healthy ? current.checkedAt : (prev?.lastHealthyAt || null),
  lastAlertAt: alertType ? now : (prev?.lastAlertAt || null),
};
const safeName = String(current.monitorName).replace(/[<>]/g, '').slice(0, 80);
const problemList = current.issues.slice(0, 8).map(v => '• ' + v).join('\n');
const prefix = alertType === 'RECOVERED' ? ':white_check_mark: *RECOVERED*' : ':rotating_light: *CANARY CHECK FAILED*';
const text = `${prefix}: ${safeName}\n*Status:* ${current.responseStatus ?? 'network error'} | *Check:* ${current.checkedAt}\n${problemList || 'All configured business assertions pass.'}\n*Monitor key:* ${key}\n*Execution:* ${$execution.id || '(manual)'}`;
return [{ json: {
  ...current, alertType, notify: Boolean(alertType),
  slackText: text,
  previousHealth: prev ? (prev.healthy ? 'healthy' : 'unhealthy') : 'no baseline',
  statePersistence: $execution.mode === 'production' ? 'production' : 'manual-test-no-persistence',
} }];
